li.OKResult:

me:AddMsg(XT("[NAME]解开红绳拆开新手礼包，箱中静静躺着以下宝物："));
me:DropAwardItem("Item_Wonder_QianKunLingJing", 1);
me:DropAwardItem("Item_SkyStone", 1);
me:DropAwardItem("Item_BossZhuLong_TianLin", 1);
me:DropAwardItem("Item_MiBao_YinYangZhenTu", 1);
me:DropAwardItem("Item_BossZhuLong_LongYu", 1);
me:DropAwardItem("Item_BossZhuLong_Eye", 2);
me:DropAwardItem("Item_ParasolWood", 1);
me:DropAwardItem("Item_StarEssence", 1);
me:DropAwardItem("Item_YaoLeather1", 1);
me:DropAwardItem("Item_Dan_FiveBaseFromLife", 1);
story:RemoveBindItem();


me:AddMsg(XT("[NAME]撬开锈死的锁扣，匣中封存的古修神念散逸而出，隐约指向几处上古修行者的踪迹……"));
local ok, err = pcall(function()
	local Evt = GameEventMgr or CS.XiaWorld.GameEventMgr.Instance;
	for i = 1, 3 do
		Evt:TriggerEvent(97);
	end
end);
if not ok then
	print("[JadeStartMod] 古修秘匣触发失败: " .. tostring(err));
end
story:RemoveBindItem();


me:AddMsg(XT("[NAME]解开红绳打开礼包，箱底一缕气运散作清风，飘向山门之外……"));
local ok, err = pcall(function()
	GameMain:GetMod("JadeStartMod"):SpawnBlessedMortal(me);
end);
if ok then
	me:AddMsg(XT("不多时，山门外来了一群凡人，说是流落至此，愿在山门求一处安身之所。"));
else
	print("[JadeStartMod] 招贤礼包召唤失败: " .. tostring(err));
	me:AddMsg(XT("可山门外始终不见人影，那缕气运也渐渐淡了。"));
end
story:RemoveBindItem();
